p=argparse.ArgumentParser();p.add_argument('census',type=Path);p.add_argument('probe',type=Path);p.add_argument('out',type=Path);p.add_argument('--limit',type=int,default=256);a=p.parse_args();assert 1<=a.limit<=256;a.out.mkdir(parents=True,exist_ok=False);read=lambda p:json.loads(Path(p).read_text(encoding='utf-8'));c=read(a.census/'summary.json');assert sha(a.census/'candidates.json')==c['candidates_sha256'];probe=read(a.probe/'summary.json');assert probe['fault']['reason']==27 and probe['game_aot_execution'] and not probe['original_byte_cpu_execution'];assert sha(a.probe/'startup.exe')==probe['executable_sha256'] and sha(a.probe/'native-calls.jsonl')==probe['control_trace_sha256'];pc=int(probe['fault']['pc'],16);known={r['pc'] for r in read(a.probe/'compilation-targets.json')};eligible=[r for r in read(a.census/'candidates.json') if r['pc'] not in known];assert pc in {r['pc'] for r in eligible};selected=sorted(sorted(eligible,key=lambda r:(abs(r['pc']-pc),r['pc']))[:a.limit],key=lambda r:r['pc'])
